package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;
/** Own small MLP, trained from random weights on original operator-edit examples. Not a general code LM. */
final class JavaEditModel{
 static final int D=96,H=24,K=6;static final String[] OPS={"+","-","*","/","min","max"};
 static final String[][] TRAIN={{"sumar los valores","agregar ambas cantidades","suma de dos numeros","calcular el total sumando","adicion de cantidades","juntar dos importes"},{"restar los valores","quitar la segunda cantidad","calcular la diferencia","disminuir el primer valor","sustraer el segundo numero","descontar una cantidad"},{"multiplicar los valores","producto de dos numeros","cantidad por precio","multiplica los tiempos","calcular producto","escalar por un factor"},{"dividir los valores","repartir en partes iguales","calcular cociente","cuadros divididos por fps","segundos dividiendo cuadros por cuadros por segundo","divide el total entre cantidad"},{"elegir el minimo","usar el menor valor","tomar la cantidad menor","limitar al mas pequeno","calcular minimo de dos numeros","conservar el menor"},{"elegir el maximo","usar el mayor valor","tomar la cantidad mayor","limitar al mas grande","calcular maximo de dos numeros","conservar el mayor"}};
 static final String[][] HELDOUT={{"quiero sumar ambas cantidades","sumar dos valores"},{"quiero restar ambas cantidades","restar dos valores"},{"quiero multiplicar ambas cantidades","multiplicar dos valores"},{"quiero dividir ambas cantidades","dividir dos valores"},{"quiero el minimo entre cantidades","elegir el menor valor"},{"quiero el maximo entre cantidades","elegir el mayor valor"}};
 static final String[][] FINAL={{"sumar el primer numero y el segundo","adicion de dos valores"},{"restar una cantidad de otra","sustraer cantidades"},{"multiplicar dos importes","producto de cantidades"},{"dividir el total","cociente de dos valores"},{"minimo entre dos valores","menor cantidad"},{"maximo entre dos valores","mayor cantidad"}};
 static final String[] CONTEXTS={"","ambas cantidades","dos valores","dos numeros","primer valor segundo valor","total cantidad"};
 static final Set<String> VOCAB=vocab();static Set<String> vocab(){Set<String> words=new HashSet<>();for(String[] group:TRAIN)for(String sentence:group)words.addAll(AdaptiveMemory.terms(sentence));return words;}
 final float[][] a=new float[H][D],b=new float[K][H];final float[] bias=new float[K];int trainCorrect,testCorrect,finalCorrect;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-java-edit-model",0);}
 static boolean covered(String text){for(String word:AdaptiveMemory.terms(text))if(VOCAB.contains(word))return true;return false;}
 static float[] features(String text){Set<String> words=AdaptiveMemory.terms(text);float[] x=new float[D];for(String word:words){if(!VOCAB.contains(word))continue;x[(word.hashCode()&Integer.MAX_VALUE)%(D-1)]+=1;for(int i=0;i+3<=word.length();i++)x[(word.substring(i,i+3).hashCode()&Integer.MAX_VALUE)%(D-1)]+=.2f;}float n=0;for(float v:x)n+=v*v;if(n>0){n=(float)Math.sqrt(n);for(int i=0;i<D-1;i++)x[i]/=n;}x[D-1]=1;return x;}
 JavaEditModel(){Random random=new Random(48117);for(float[] row:a)for(int i=0;i<row.length;i++)row[i]=(random.nextFloat()-.5f)*.3f;for(float[] row:b)for(int i=0;i<row.length;i++)row[i]=(random.nextFloat()-.5f)*.3f;}
 float[] hidden(float[] x){float[] h=new float[H];for(int i=0;i<H;i++){float s=0;for(int d=0;d<D;d++)s+=a[i][d]*x[d];h[i]=(float)Math.tanh(s);}return h;}
 float[] output(float[] h){float[] p=new float[K];float max=-100;for(int k=0;k<K;k++){p[k]=bias[k];for(int i=0;i<H;i++)p[k]+=b[k][i]*h[i];max=Math.max(max,p[k]);}float sum=0;for(int k=0;k<K;k++){p[k]=(float)Math.exp(p[k]-max);sum+=p[k];}for(int k=0;k<K;k++)p[k]/=sum;return p;}
 int predict(String text){float[] p=output(hidden(features(text)));int best=0;for(int i=1;i<K;i++)if(p[i]>p[best])best=i;return best;}
 float confidence(String text){float[] p=output(hidden(features(text)));float first=0,second=0;for(float v:p)if(v>first){second=first;first=v;}else second=Math.max(second,v);return first-second;}
 void train(){for(int epoch=0;epoch<100;epoch++)for(int row=0;row<6;row++)for(int variant=0;variant<CONTEXTS.length;variant++)for(int offset=0;offset<K;offset++){int target=(offset+epoch)%K;float[] x=features(TRAIN[target][row]+" "+CONTEXTS[variant]),h=hidden(x),p=output(h),grad=new float[H];for(int k=0;k<K;k++){float error=(k==target?1:0)-p[k];for(int i=0;i<H;i++)grad[i]+=error*b[k][i];for(int i=0;i<H;i++)b[k][i]+=.09f*error*h[i];bias[k]+=.09f*error;}for(int i=0;i<H;i++)for(int d=0;d<D;d++)a[i][d]+=.09f*grad[i]*(1-h[i]*h[i])*x[d];}for(int k=0;k<K;k++){for(String q:TRAIN[k])if(predict(q)==k)trainCorrect++;for(String q:HELDOUT[k])if(predict(q)==k)testCorrect++;for(String q:FINAL[k])if(predict(q)==k)finalCorrect++;}}
 JSONObject json()throws Exception{JSONArray first=new JSONArray(),second=new JSONArray(),offset=new JSONArray();for(float[] row:a)first.put(new JSONArray(row));for(float[] row:b)second.put(new JSONArray(row));for(float f:bias)offset.put(f);return new JSONObject().put("version",1).put("first",first).put("second",second).put("bias",offset).put("training",trainCorrect).put("heldout",testCorrect).put("final",finalCorrect);}
 static JavaEditModel read(String raw)throws Exception{JSONObject j=new JSONObject(raw);if(j.getInt("version")!=1)throw new IllegalArgumentException("Modelo incompatible.");JavaEditModel m=new JavaEditModel();JSONArray aa=j.getJSONArray("first"),bb=j.getJSONArray("second"),bi=j.getJSONArray("bias");if(aa.length()!=H||bb.length()!=K||bi.length()!=K)throw new IllegalArgumentException("Dimensiones inválidas.");for(int i=0;i<H;i++){JSONArray row=aa.getJSONArray(i);if(row.length()!=D)throw new IllegalArgumentException("Dimensiones inválidas.");for(int d=0;d<D;d++)m.a[i][d]=finite(row.getDouble(d));}for(int k=0;k<K;k++){JSONArray row=bb.getJSONArray(k);if(row.length()!=H)throw new IllegalArgumentException("Dimensiones inválidas.");for(int i=0;i<H;i++)m.b[k][i]=finite(row.getDouble(i));m.bias[k]=finite(bi.getDouble(k));}m.trainCorrect=j.getInt("training");m.testCorrect=j.getInt("heldout");m.finalCorrect=j.getInt("final");return m;}
 static float finite(double value){if(Double.isNaN(value)||Double.isInfinite(value)||Math.abs(value)>100)throw new IllegalArgumentException("Peso inválido.");return (float)value;}
 static String train(Context c)throws Exception{JavaEditModel model=new JavaEditModel();JavaChat.phase("Entrenando el especialista propio en Android…");model.train();if(model.trainCorrect<34||model.testCorrect<8)throw new IllegalArgumentException("No pasó la evaluación mínima; conservé el modelo anterior.");String old=prefs(c).getString("model","");if(!prefs(c).edit().putString("backup",old).putString("model",model.json().toString()).putInt("revision",prefs(c).getInt("revision",0)+1).commit())throw new java.io.IOException("No pude guardar el entrenamiento.");return "Entrené desde cero el especialista Java en este dispositivo.\nEntrenamiento: "+model.trainCorrect+"/36; validación de desarrollo: "+model.testCorrect+"/12; evaluación separada: "+model.finalCorrect+"/12.\nPredice seis operaciones para editar un return aritmético. No es un modelo generador de programas Java generales.";}
 static JavaEditModel current(Context c)throws Exception{String raw=prefs(c).getString("model","");if(raw.isEmpty())throw new IllegalArgumentException("Primero decí ‘entrena especialista java’.");return read(raw);}
}
